#!/usr/bin/env node

"use strict";

const parseArgs = require("minimist");
const Jibo = require("@jibo/jibo-server-client");

let args = process.argv.slice(2);
const argopts = {
    string: ["credentials", "subsystem", "filter"],
    boolean: ["h", "help"]
};
let argv = parseArgs(args, argopts);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help                print this message");
    console.log("  --credentials FILE       path to credentials.json");
    console.log("  --subsystem SUBSYSTEM    subsystem to update");
    console.log("  --filter STRING          filter for updates");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (!argv.credentials) {
    console.log("ERROR: credentials file not specified!");
    usage();
    process.exit(1);
}

if (!argv.subsystem) {
    console.log("ERROR: subsystem not specified!");
    usage();
    process.exit(1);
}

Jibo.config.loadFromPath(argv.credentials);

let update = new Jibo.Update();

let params = {
    subsystem: argv.subsystem
};

if (argv.filter) {
    params.filter = argv.filter;
}

update.listUpdates(params, function(err, data) {
    if (err) {
        console.log(JSON.stringify({error: err}));
        process.exit(1);
    } else {
        console.log(JSON.stringify({updates: data}, null, "    "));
        process.exit(0);
    }
});
